export function importedEquipment(id: string) {
  const equipment = IMPORTED_EQUIPMENT.find(equipment => equipment.id === id) ?? REAL_EQUIPMENT.find(equipment => equipment.id === id);
  const url = pilotEquipmentUrl(id);
  return equipment && url ? { ...equipment, asset: { ...equipment.asset, url } } : equipment;
}
